CREATE POLICY "Doctorands upload doctoral files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='doctoral-documents' AND EXISTS (SELECT 1 FROM public.doctoral_profiles p WHERE p.user_id=auth.uid() AND (storage.foldername(name))[1]=p.id::text AND p.status='active'));
CREATE POLICY "Doctoral participants read files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='doctoral-documents' AND EXISTS (SELECT 1 FROM public.doctoral_profiles p WHERE (storage.foldername(name))[1]=p.id::text AND (p.user_id=auth.uid() OR p.coordinator_user_id=auth.uid() OR public.can_manage_doctoral(auth.uid()))));
CREATE POLICY "Doctoral participants delete files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id='doctoral-documents' AND EXISTS (SELECT 1 FROM public.doctoral_profiles p WHERE (storage.foldername(name))[1]=p.id::text AND (p.user_id=auth.uid() OR p.coordinator_user_id=auth.uid() OR public.can_manage_doctoral(auth.uid()))));